$base = __DIR__;

function fmWrite($base, $rel, $gz_b64) {
    $dir = dirname("$base/$rel");
    if (!is_dir($dir)) mkdir($dir, 0755, true);
    return file_put_contents("$base/$rel", gzdecode(base64_decode($gz_b64))) !== false;
}

